import type { Metadata } from 'next';
import type { Property } from '@/types';

export const SITE_URL = (process.env.APP_URL ?? 'https://habbaa.in').replace(/\/$/, '');
export const SITE_NAME = 'Villa 19 by Habbaa';
export const BRAND = 'Habbaa';

/** Generated by src/app/opengraph-image.tsx. Listed explicitly because a page's
 *  own openGraph object replaces the inherited one, image included. */
export const DEFAULT_SHARE_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'Villa 19 by Habbaa: Premium 4-Bedroom Private Urban Villa',
};

interface PageSeo {
  /** Rendered through the root template as "<title> | Villa 19 by Habbaa". */
  title: string;
  description: string;
  /** Path from the site root, e.g. "/rooms". Becomes the canonical URL. */
  path: string;
  /** Use for a title that must not get the template suffix (the homepage). */
  absoluteTitle?: boolean;
  noindex?: boolean;
  ogType?: 'website' | 'article';
}

/**
 * Page metadata with canonical URL, Open Graph and Twitter fields in one place.
 * Next.js replaces a nested `openGraph` object wholesale rather than merging it
 * with the root layout's, so every page must carry the shared fields itself.
 */
export function pageMetadata({ title, description, path, absoluteTitle, noindex, ogType = 'website' }: PageSeo): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    robots: noindex ? { index: false, follow: true } : undefined,
    openGraph: {
      type: ogType,
      locale: 'en_IN',
      siteName: SITE_NAME,
      url: path,
      title: fullTitle,
      description,
      images: [DEFAULT_SHARE_IMAGE],
    },
    twitter: { card: 'summary_large_image', title: fullTitle, description, images: [DEFAULT_SHARE_IMAGE.url] },
  };
}

// ── Structured data (schema.org JSON-LD) ─────────────────────────────────────

const ORG_ID = `${SITE_URL}/#organization`;
const LODGING_ID = `${SITE_URL}/#lodging`;

export function organizationJsonLd() {
  return {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    '@id': ORG_ID,
    name: BRAND,
    url: SITE_URL,
    logo: `${SITE_URL}/habbaa-logo.png`,
    email: process.env.PROPERTY_EMAIL ?? 'reservations@habbaa.com',
  };
}

interface LodgingInput {
  property: Property;
  images: string[];
  amenities: string[];
  telephone?: string;
}

/**
 * The villa as a LodgingBusiness, built from database fields so an edit made
 * in Ooruda Villa (address, times, capacity, photos) updates it automatically.
 * No review ratings: Google ignores self-hosted reviews for LocalBusiness.
 */
export function lodgingJsonLd({ property, images, amenities, telephone }: LodgingInput) {
  const rupees = (paise: number) => Math.round(paise / 100);
  return {
    '@context': 'https://schema.org',
    '@type': 'LodgingBusiness',
    '@id': LODGING_ID,
    name: property.name,
    description: property.description,
    url: SITE_URL,
    // Gallery images are served from /gallery on this site; schema.org needs
    // absolute URLs, so relative paths are resolved against SITE_URL.
    image: images.length ? images.map((u) => (/^https?:\/\//.test(u) ? u : `${SITE_URL}${u}`)) : undefined,
    telephone: telephone ? `+${telephone.replace(/\D/g, '')}` : undefined,
    parentOrganization: { '@id': ORG_ID },
    address: {
      '@type': 'PostalAddress',
      streetAddress: property.address,
      addressLocality: property.city,
      addressRegion: property.state,
      postalCode: property.pincode,
      addressCountry: 'IN',
    },
    geo: property.geo_lat && property.geo_lng
      ? { '@type': 'GeoCoordinates', latitude: property.geo_lat, longitude: property.geo_lng }
      : undefined,
    checkinTime: property.check_in_time,
    checkoutTime: property.check_out_time,
    numberOfRooms: property.bedroom_count,
    maximumAttendeeCapacity: property.max_occupancy,
    petsAllowed: false,
    // Free text for search engines; mirrors the booking widget's "starting from" line.
    priceRange: `From ₹${rupees(Math.min(property.base_nightly_rate, property.weekend_nightly_rate)).toLocaleString('en-IN')} per night, plus GST`,
    currenciesAccepted: 'INR',
    amenityFeature: [
      ...amenities.map((name) => ({ '@type': 'LocationFeatureSpecification', name, value: true })),
      // Stated absences stop assistants assuming a pool or staff.
      ...['Swimming pool', 'In-house cook', 'Beachfront'].map((name) => ({ '@type': 'LocationFeatureSpecification', name, value: false })),
    ],
  };
}

export function breadcrumbJsonLd(trail: { name: string; path: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [{ name: 'Home', path: '/' }, ...trail].map((c, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: c.name,
      item: `${SITE_URL}${c.path === '/' ? '' : c.path}`,
    })),
  };
}

/** Q&A pairs exactly as shown on the page. Google no longer shows FAQ rich results
 *  for most sites, but answer engines read this directly. */
export function faqJsonLd(faqs: { question: string; answer: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((f) => ({
      '@type': 'Question',
      name: f.question,
      acceptedAnswer: { '@type': 'Answer', text: f.answer },
    })),
  };
}
